-- composition of rule kernels L:simplify_expressions x P:join_selection (datafusion), template union
SELECT count(*) FROM (SELECT 1 AS k FROM (SELECT TRUE AS c0, 1.5::numeric AS c1) AS ka UNION ALL SELECT 2 AS k FROM (SELECT '2000-01-01'::date AS c0 FROM (t4 AS a1 JOIN t4 AS a2 ON (a1.c0 = a2.c0)) GROUP BY a2.c0, a2.c3 UNION ALL (SELECT '2024-01-01'::date AS c0 UNION SELECT '2024-01-01'::date AS c0)) AS kb) AS u;
